import 'package:flutter/material.dart';import '../services/app_services.dart';import '../models/room.dart';import 'post_room.dart';
class LandlordHome extends StatelessWidget{const LandlordHome({super.key});Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Landlord dashboard'),actions:[IconButton(onPressed:()=>auth.signOut(),icon:const Icon(Icons.logout))]),body:StreamBuilder<List<Room>>(stream:RoomService().myListings(auth.currentUser!.uid),builder:(c,s){final rs=s.data??[];return ListView(padding:const EdgeInsets.all(16),children:[FilledButton.icon(onPressed:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>const PostRoom())),icon:const Icon(Icons.add),label:const Text('Post a new room')),const SizedBox(height:20),const Text('Your listings',style:TextStyle(fontSize:22,fontWeight:FontWeight.bold)),const SizedBox(height:8),...rs.map((r)=>Card(child:ListTile(leading:r.photos.isEmpty?const Icon(Icons.home):Image.network(r.photos.first,width:60,fit:BoxFit.cover),title:Text(r.title),subtitle:Text('Rs. ${r.rent} • ${r.status}'),trailing:Switch(value:r.status=='approved',onChanged:r.status=='approved'?(v)=>RoomService().setAvailability(r.id,v):null))))]));});}
